// Build a compact, LLM-friendly candidate list and the system/user prompt used
// to semantically match the caller's query to a REAL catalog.json entry.
const catalog = $input.first().json; // parsed catalog.json (fetched live from GitHub)
const rows = Array.isArray(catalog.rows) ? catalog.rows : [];

const webhookItem = $('Caller Query In').item.json;
const callerQuery = (webhookItem.body && webhookItem.body.query)
  || webhookItem.query
  || '';

// Only real "indicator" rows are offered as answer candidates -- boundary/
// basemap rows (kind: "boundary_or_basemap") are not indicator data and are
// never a valid "table" answer to a data question.
const candidates = rows
  .filter((r) => r.kind === 'indicator')
  .map((r) => ({
    title: r.title,
    field: r.field,
    topic: r.topic_guess,
    snippet: r.snippet,
  }));


// Deterministic lexical PRE-FILTER (fixes "lost in the middle"): a ~24B model reliably misses a
// relevant row buried deep in a 150+ candidate list. Rank candidates by German-aware token
// overlap with the caller's question and keep only the top K before the LLM ever sees them.
// Pure/deterministic; the LLM still makes the final semantic pick from the shortlist.
const STOP = new Set('der die das und in im an auf von zu je pro wie viele hoch ist gibt es eine einen den dem'.split(' '));
const fold = (x) => (x || '').toLowerCase().replace(/ä/g, 'a').replace(/ö/g, 'o').replace(/ü/g, 'u').replace(/ß/g, 'ss');
const toks = (x) => {
  const out = new Set();
  (fold(x).match(/[a-z]{4,}/g) || []).forEach((w) => { if (!STOP.has(w)) { out.add(w); out.add(w.slice(0, 6)); } });
  return out;
};
const qtok = toks(callerQuery);
const overlap = (c) => {
  const b = toks((c.title || '') + ' ' + (c.snippet || '') + ' ' + (c.topic || ''));
  let n = 0; qtok.forEach((w) => { if (b.has(w)) n += 1; }); return n;
};
const SHORTLIST_K = 15;
const shortlisted = candidates
  .map((c) => ({ c, s: overlap(c) }))
  .sort((a, b) => b.s - a.s)
  .slice(0, SHORTLIST_K)
  .map((x) => x.c);

const systemPrompt = [
  'You are the query-understanding stage of a German public-data call-center assistant.',
  'You will be given a caller question and a list of REAL, LIVE table entries from the',
  "German government Deutschlandatlas API. Your ONLY job is to pick the entry whose",
  '"snippet" most plausibly answers the caller\'s question (semantic match on meaning,',
  'not keyword overlap), and to extract any German place name the caller mentioned.',
  '',
  'Rules:',
  '- "table" MUST be copied EXACTLY (verbatim) from one of the given "title" values.',
  '  Never invent, translate, abbreviate, or guess a table name not in the list.',
  '- Each candidate has a "topic" label that is a ROUGH, sometimes-wrong hint from a',
  '  keyword heuristic. Do NOT rely on it. Match on "snippet" and "title"; a snippet',
  '  that describes the asked-about data IS a match even if its "topic" looks unrelated.',
  '- If nothing in the list genuinely answers the question (the caller asks about a',
  '  topic this dataset does not cover), set "matched" false and leave "table" null.',
  '  Judge this from the snippets themselves, NOT from any assumption about what the',
  '  dataset does or does not contain. Do not force a bad match.',
  '- If there is no exact match but a nearby table in the list answers a related,',
  '  reasonable reformulation of the question, pick that table, set "matched" true',
  '  AND "reformulated" true, and explain the reformulation in "reformulation_note".',
  '  The reformulation must still be a real table from the list -- never a fabricated one.',
  '- Write "no_match_reason" in GERMAN (the caller is German-speaking).',
  '- "place_name" is the German place (city/municipality) the caller named, verbatim',
  '  as they said it, or null if none was named.',
  '- Respond with ONLY a JSON object, no prose, no markdown fence:',
  '  {"matched": boolean, "table": string|null, "reformulated": boolean,',
  '   "reformulation_note": string|null, "place_name": string|null,',
  '   "no_match_reason": string|null}',
].join('\n');

const userPrompt = JSON.stringify({
  caller_question: callerQuery,
  candidate_tables: shortlisted,
});

return [{
  json: {
    callerQuery,
    llmSystem: systemPrompt,
    llmUser: userPrompt,
  },
}];

// Deterministically validate the LLM's catalog-match output. NEVER trust the
// model's proposed table name blindly -- it must exist verbatim in catalog.json.
const catalog = $('Fetch Catalog (GitHub)').first().json;
const rows = Array.isArray(catalog.rows) ? catalog.rows : [];
const promptCtx = $('Build Catalog Match Prompt').first().json;
const resp = $input.first().json;

function parseLoose(text) {
  if (typeof text !== 'string') return null;
  try { return JSON.parse(text); } catch (e) { /* fall through */ }
  const m = /^```(?:json)?\s*([\s\S]*?)\s*```$/.exec(text.trim());
  if (m) { try { return JSON.parse(m[1]); } catch (e) { /* fall through */ } }
  return null;
}

const content = resp && resp.choices && resp.choices[0] && resp.choices[0].message
  ? resp.choices[0].message.content
  : null;
const parsed = parseLoose(content);

if (!parsed) {
  return [{ json: {
    matched: false,
    no_match_reason: 'The catalog-matching LLM call did not return valid JSON; failing closed rather than guessing a table.',
    callerQuery: promptCtx.callerQuery,
  } }];
}

const row = parsed.matched
  ? rows.find((r) => r.kind === 'indicator' && r.title === parsed.table)
  : null;

if (parsed.matched && !row) {
  return [{ json: {
    matched: false,
    no_match_reason: `The model proposed table "${parsed.table}", which does not exist verbatim in catalog.json -- failing closed rather than querying a hallucinated table.`,
    callerQuery: promptCtx.callerQuery,
  } }];
}

return [{ json: {
  matched: !!parsed.matched,
  reformulated: !!parsed.reformulated,
  reformulation_note: parsed.reformulation_note || null,
  place_name: parsed.place_name || null,
  no_match_reason: parsed.no_match_reason || null,
  callerQuery: promptCtx.callerQuery,
  catalogRow: row, // real row object: title, snippet, url, field, kind, topic_guess, ...
} }];

const d = $input.first().json;
const text = d.no_match_reason
  ? `Entschuldigung, dazu finde ich im Deutschlandatlas keine passenden Live-Daten. Grund: ${d.no_match_reason} Bitte fragen Sie zu einem anderen Thema wie Beschäftigung, Wohnen, Bevölkerung, Bildung, Umwelt, Gesundheit, Finanzen oder Infrastruktur.`
  : 'Entschuldigung, dazu finde ich im Deutschlandatlas keine passenden Live-Daten. Bitte formulieren Sie Ihre Frage anders.';

return [{ json: {
  text,
  meta: {
    matched: false,
    no_match_reason: d.no_match_reason || null,
    caller_query: d.callerQuery || null,
    grounded: true, // no fact was spoken -- a fixed, non-fabricated refusal
  },
} }];

// Per this project's own live-verified finding (see catalog.json's
// "query_template_caveat"): the README's documented query URL hardcodes
// layer id 0, but that is frequently wrong -- many tables' real queryable
// Feature Layer lives at id 3-6 instead, and id 0 is often an unqueryable
// cached Raster Layer. Always discover the real id from MapServer?f=json,
// never assume it.
const meta = $input.first().json; // MapServer?f=json response
const match = $('Validate Catalog Match').first().json;

const layers = Array.isArray(meta.layers) ? meta.layers : [];
const capabilities = typeof meta.capabilities === 'string' ? meta.capabilities : '';
const featureLayer = layers.find((l) => l.type === 'Feature Layer');

const layerId = featureLayer ? featureLayer.id : 0;
const queryable = capabilities.split(',').map((s) => s.trim()).includes('Query');

return [{ json: {
  ...match,
  layerId,
  readmeLayer0Mismatch: layerId !== 0,
  queryable,
  serviceCapabilities: capabilities,
  serviceHadNoFeatureLayer: !featureLayer,
} }];

const d = $input.first().json;
return [{ json: {
  ...d,
  dataError: true,
  dataErrorMessage: d.serviceHadNoFeatureLayer
    ? `Service capabilities are "${d.serviceCapabilities}" and no Feature Layer was found in MapServer?f=json -- this table is a cached map/basemap layer with no queryable attribute data.`
    : `Service capabilities are "${d.serviceCapabilities}" (no "Query" capability) -- this table's data cannot be fetched via the query endpoint at all.`,
  featuresOut: [],
  fields: [],
  whereClauseUsed: null,
} }];

// Deliberately NEVER send resultRecordCount: some services (e.g.
// pendel_a_HA2023, VG250_LAN1217_grenzen) reject it outright
// (supportsPagination: false -> "Pagination is not supported.") -- a real,
// live-verified API quirk (catalog.json's "no_pagination_fallback"). Omitting
// it entirely and capping the *response* client-side (below) avoids the
// whole class of error rather than needing a detect-and-retry round trip.
const body = $input.first().json;
const ctx = $('Pick Indicator Layer').first().json;

const errMsg = body && body.error ? (body.error.message || JSON.stringify(body.error)) : null;

if (errMsg) {
  return [{ json: {
    ...ctx,
    dataError: true,
    dataErrorMessage: `MapServer query error while discovering schema: ${errMsg}`,
    featuresOut: [],
  } }];
}

const fields = Array.isArray(body.fields) ? body.fields.map((f) => f.name) : [];
const sample = (Array.isArray(body.features) ? body.features : [])
  .slice(0, 5)
  .map((f) => f.attributes);

return [{ json: {
  ...ctx,
  discoveredFields: fields,
  discoveredSample: sample,
} }];

// Confirm the real field names for THIS table live -- geographic granularity
// and schema vary per table, so never assume a fixed schema across the 199
// catalog rows (per this project's own architecture doc).
const d = $input.first().json;
const fields = Array.isArray(d.discoveredFields) ? d.discoveredFields : [];
const REGION_NAME_FIELDS = ['GEN', 'name', 'NAME'];
const directNameField = REGION_NAME_FIELDS.find((f) => fields.includes(f)) || null;

return [{ json: {
  ...d,
  fields,
  hasDirectNameField: !!directNameField,
  directNameField,
} }];

const d = $input.first().json;
// Esri's where-clause is SQL-like; double any single quote in the caller-
// supplied place name (standard SQL-string escaping) before interpolating.
const place = String(d.place_name).replace(/'/g, "''");
const field = d.directNameField;
const whereClause = `UPPER(${field}) LIKE UPPER('%${place}%')`;

return [{ json: {
  ...d,
  whereClauseUsed: whereClause,
  placeFilterApplied: true,
  placeFilterUnavailableReason: null,
  boundaryResolved: null,
} }];

// Region resolution uses the Deutschlandatlas' OWN administrative boundary
// layer (VG250_Verbandsgemeinden1219_Punkt) -- never a third-party geocoder,
// per this project's already-decided architecture (see README). Still
// discover the real layer id live rather than hardcoding it, consistent
// with the same rule applied to the 199 indicator tables.
const meta = $input.first().json; // boundary MapServer?f=json response
const ctx = $('Finalize Schema').first().json; // carried caller/table context

const layers = Array.isArray(meta.layers) ? meta.layers : [];
const capabilities = typeof meta.capabilities === 'string' ? meta.capabilities : '';
const featureLayer = layers.find((l) => l.type === 'Feature Layer');
const layerId = featureLayer ? featureLayer.id : 0;
const queryable = capabilities.split(',').map((s) => s.trim()).includes('Query');

const place = String(ctx.place_name || '').replace(/'/g, "''");

return [{ json: {
  ...ctx,
  boundaryUrl: 'https://www.karto365.de/hosting/rest/services/VG250_Verbandsgemeinden1219_Punkt/MapServer',
  boundaryLayerId: layerId,
  boundaryQueryable: queryable,
  boundaryWhereClause: `UPPER(GEN) LIKE UPPER('%${place}%')`,
} }];

const body = $input.first().json; // boundary query response
const ctx = $('Pick Boundary Layer').first().json;

const errMsg = body && body.error ? (body.error.message || JSON.stringify(body.error)) : null;
const features = !errMsg && Array.isArray(body.features) ? body.features : [];

let boundaryResolved = null;
if (features.length > 0) {
  const attrs = features[0].attributes || {};
  boundaryResolved = {
    matchedName: attrs.GEN || null,
    type: attrs.BEZ || null,
    ars: attrs.ARS || null,
    level: 'Verbandsgemeinde',
  };
}

// The resolved boundary code is NOT used as a join key into the indicator
// table: the only queryable boundary layer here is Verbandsgemeinde-level
// (9-digit ARS) while most indicator tables are Kreis-level (Gebiets-
// kennziffer) -- a different granularity. Guessing a numeric-prefix join
// across that mismatch could silently return the wrong region's number,
// which this project's grounding requirement forbids. The boundary match is
// used only to confirm/canonicalize the place name for the caller.
return [{ json: {
  ...ctx,
  boundaryResolved,
  boundaryMatchFailed: !boundaryResolved,
  whereClauseUsed: '1=1',
  placeFilterApplied: false,
  placeFilterUnavailableReason:
    `Table "${ctx.catalogRow.title}" has no place-name field of its own ` +
    `(fields present: ${ctx.fields.join(', ')}); ` +
    (boundaryResolved
      ? `the caller's place could be confirmed as "${boundaryResolved.matchedName}" against the boundary layer, but this table cannot be filtered to it -- returning its available sample data instead.`
      : `and the named place could not be confirmed against the boundary layer either -- returning the table's available sample data instead.`),
} }];

// No place name was given (or the table has one but the caller didn't name
// a place) -- query without a place filter and let the phrasing step be
// honest about scope.
const d = $input.first().json;
return [{ json: {
  ...d,
  whereClauseUsed: '1=1',
  placeFilterApplied: false,
  placeFilterUnavailableReason: null,
  boundaryResolved: null,
} }];

// Exactly one of the three where-clause-builder branches ran upstream of
// this node -- recover its carried context by name (n8n keeps every node's
// output addressable by name for the whole execution, even branches that
// did not run simply throw when referenced, hence the try/catch probe).
const body = $input.first().json; // final indicator query response

function firstDefined(...fns) {
  for (const fn of fns) {
    try {
      const v = fn();
      if (v) return v;
    } catch (e) { /* that branch did not execute in this run */ }
  }
  return null;
}

const ctx = firstDefined(
  () => $('Build Where Clause Direct Filter').first().json,
  () => $('Check Boundary Match').first().json,
  () => $('Build Where Clause No Filter').first().json,
) || $('Finalize Schema').first().json;

const errMsg = body && body.error ? (body.error.message || JSON.stringify(body.error)) : null;
const features = !errMsg && Array.isArray(body.features) ? body.features : [];
// Cap what reaches the phrasing LLM -- some tables return hundreds/thousands
// of rows when queried unfiltered (e.g. pendel_a_HA2023's ~2000-row OD
// matrix); a handful of real sample rows is enough to answer or to honestly
// describe what's available, and keeps the prompt bounded.
const featuresOut = features.slice(0, 10).map((f) => f.attributes);

return [{ json: {
  ...ctx,
  dataError: !!errMsg,
  dataErrorMessage: errMsg,
  noRowsFound: !errMsg && featuresOut.length === 0,
  featuresOut,
} }];

// The single grounding gate: the phrasing LLM is instructed, in-band, to use
// ONLY facts literally present in live_api_data -- nothing recalled,
// inferred, calculated, or guessed. This node builds that prompt for both
// the "real data available" and the "no usable data" case; it never
// synthesizes a data-shaped answer itself.
const d = $input.first().json;
const featuresOut = Array.isArray(d.featuresOut) ? d.featuresOut : [];
const hasRealData = !d.dataError && !d.noRowsFound && featuresOut.length > 0;

const table = d.catalogRow || {};
const callerQuery = d.callerQuery || '';

let systemPrompt;
let userPayload;

if (hasRealData) {
  const lines = [
    'You are a German-speaking voice call-center assistant for public regional',
    'statistics (Deutschlandatlas). Below is REAL data returned just now, live,',
    `from the official German government Feature Service for table "${table.title}"`,
    `("${table.snippet}"), value field "${table.field}".`,
    '',
    'STRICT RULES (never break these):',
    '- Use ONLY facts, numbers, and place names literally present in the JSON below.',
    '- NEVER add, infer, calculate, round, compare, or guess any fact not present',
    '  in this JSON -- not even something that "sounds right".',
    '- If the JSON does not fully answer the caller, say plainly what is and is not',
    '  available; do not fill the gap with invented information.',
  ];
  if (d.placeFilterApplied === false && d.placeFilterUnavailableReason) {
    lines.push(`- ${d.placeFilterUnavailableReason}`);
  }
  if (d.reformulated) {
    lines.push(`- The caller's original question was reformulated: ${d.reformulation_note || ''}. Mention briefly that you're answering a related question.`);
  }
  lines.push('- Answer in 2-4 short, natural spoken sentences suitable for text-to-speech,');
  lines.push('  in the same language as the caller question.');
  systemPrompt = lines.join('\n');

  userPayload = JSON.stringify({
    caller_question: callerQuery,
    live_api_data: featuresOut,
  });
} else {
  const reason = d.dataErrorMessage || 'no matching rows were returned by the live query';
  systemPrompt = [
    'You are a German-speaking voice call-center assistant for public regional',
    'statistics (Deutschlandatlas). A live query to the real government data API',
    'just now did NOT return usable data for this caller question.',
    '',
    'STRICT RULES:',
    '- Apologize briefly and state plainly that no data is available right now --',
    '  do NOT invent a number or fact to fill the gap.',
    '- You may suggest the caller ask about a different topic (employment, housing,',
    '  demographics, education, infrastructure, environment, health, finance) since',
    '  those are the categories this dataset actually covers.',
    '- 1-3 short spoken sentences, same language as the caller question.',
  ].join('\n');

  userPayload = JSON.stringify({
    caller_question: callerQuery,
    failure_reason: reason,
  });
}

return [{ json: {
  ...d,
  llmPhraseSystem: systemPrompt,
  llmPhraseUser: userPayload,
  hasRealData,
} }];

const resp = $input.first().json;
const ctx = $('Build Phrasing Prompt').first().json;

const content = resp && resp.choices && resp.choices[0] && resp.choices[0].message
  ? String(resp.choices[0].message.content || '').trim()
  : null;

const answerText = content || (ctx.hasRealData
  ? 'Entschuldigung, ich konnte die Antwort gerade nicht formulieren, obwohl Live-Daten vorlagen.'
  : (ctx.dataErrorMessage || 'Entschuldigung, dazu liegen mir gerade keine Daten vor.'));

return [{ json: {
  text: answerText,
  meta: {
    matched: true,
    reformulated: !!ctx.reformulated,
    reformulation_note: ctx.reformulation_note || null,
    table: ctx.catalogRow ? ctx.catalogRow.title : null,
    field: ctx.catalogRow ? ctx.catalogRow.field : null,
    source_url: ctx.catalogRow ? ctx.catalogRow.url : null,
    layer_id: ctx.layerId != null ? ctx.layerId : null,
    where_clause: ctx.whereClauseUsed || null,
    place_name_requested: ctx.place_name || null,
    place_resolved: ctx.boundaryResolved || null,
    has_real_data: ctx.hasRealData,
    data_error: ctx.dataErrorMessage || null,
    live_rows_used: Array.isArray(ctx.featuresOut) ? ctx.featuresOut.length : 0,
  },
} }];
